using System.Text.Json;
try {
string directory="analysis/map-calibration/image-preprocess-trace";var allReports=new List<object>();long total=0;int cases=0;foreach(string line in File.ReadLines(directory+"/preprocess-trace.jsonl")){using var item=JsonDocument.Parse(line);int sequence=item.RootElement.GetProperty("sequence").GetInt32();string suffix=sequence.ToString("D3");byte[] image=File.ReadAllBytes(directory+"/raw-"+suffix+".gray");int width=item.RootElement.GetProperty("width").GetInt32(),height=item.RootElement.GetProperty("height").GetInt32();var expectedBytes=File.ReadAllBytes(directory+"/gaussian-"+suffix+".float");var expected=new float[expectedBytes.Length/4];Buffer.BlockCopy(expectedBytes,0,expected,0,expectedBytes.Length);
float[] kernel=new float[13];float sum=0;for(int i=0;i<13;i++){float d=MathF.Abs(i-6f);kernel[i]=MathF.Exp((d*d)/((-2f*3f)*3f));sum=sum+kernel[i];}for(int i=0;i<13;i++)kernel[i]=kernel[i]/sum;
int? kernelBits=null;if(File.Exists(directory+"/kernel-"+suffix+".float")){byte[] kb=File.ReadAllBytes(directory+"/kernel-"+suffix+".float");kernelBits=Enumerable.Range(0,13).Count(i=>BitConverter.SingleToInt32Bits(kernel[i])==BitConverter.ToInt32(kb,i*4));}
var horizontal=new float[width*height];for(int y=0;y<height;y++)for(int x=0;x<width;x++){float value=0;for(int k=0;k<13;k++)value=value+image[y*width+Math.Clamp(x+k-6,0,width-1)]*kernel[k];horizontal[y*width+x]=value;}
var reports=new List<object>();foreach(bool fma in new[]{false}){var output=new float[width*height];for(int y=0;y<height;y++)for(int x=0;x<width;x++){float value=0;for(int k=0;k<13;k++){float source=horizontal[Math.Clamp(y+k-6,0,height-1)*width+x];value=fma?MathF.FusedMultiplyAdd(kernel[k],source,value):value+kernel[k]*source;}output[y*width+x]=value;}int exact=output.Zip(expected).Count(p=>BitConverter.SingleToInt32Bits(p.First)==BitConverter.SingleToInt32Bits(p.Second));double maximum=output.Zip(expected).Max(p=>Math.Abs((double)p.First-p.Second));reports.Add(new{fma,exact,fields=expected.Length,maximum});Console.WriteLine($"Gaussian {sequence} {width}x{height}: {exact}/{expected.Length} bits, max {maximum:R}");if(exact!=expected.Length||kernelBits!=13)throw new InvalidOperationException("Native Gaussian mismatch");total+=exact;}
allReports.Add(new{sequence,width,height,kernelBits,reports});cases++;}if(cases!=12)throw new InvalidOperationException("Expected 12 native cases");Directory.CreateDirectory("analysis/map-calibration/gaussian-kernel");File.WriteAllText("analysis/map-calibration/gaussian-kernel/prototype.json",JsonSerializer.Serialize(new{cases,fields=total,diagnosticOnly=true,productionIntegrated=false,reports=allReports},new JsonSerializerOptions{WriteIndented=true}));return 0;
}catch(Exception error){Console.Error.WriteLine(error);return 1;}

